(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["cy"] = {"ui":{"skip":"Neidio i'r cynnwys","back":"← Yn ôl i AI-gile","lang.button":"Iaith: {name}","lang.dialog":"Dewis iaith","lang.search":"Chwilio am ieithoedd","lang.none":"Dim iaith yn cyfateb","lang.notYet":"Nid yw {name} wedi'i chyfieithu eto","theme.aria":"Newid rhwng y thema golau a'r thema tywyll","theme.toLight":"Newid i'r thema golau","theme.toDark":"Newid i'r thema tywyll","index.title":"AI-gile: dy dîm datblygu AI, ar un bwrdd","index.description":"Bwrdd kanban yw AI-gile ar gyfer timau AI sy'n codio. Maen nhw'n gweithio tra byddi di'n cysgu; cei un pentwr byr o bethau i'w penderfynu, eu profi a'u derbyn.","hero.logoAlt":"Eicon bwrdd AI-gile","hero.h1.html":"Dy dîm datblygu AI, ar un&nbsp;bwrdd.","hero.alpha":"🐣 Cyn-alffa caeedig","hero.alphaTitle":"Cynnar a heb ei orffen: diolch am roi cynnig arni!","hero.lede":"Maen nhw'n adeiladu tra byddi di'n cysgu. Byddi di'n deffro i un pentwr byr: ychydig o gwestiynau, ychydig o bethau i'w profi, diemwnt porffor neu ddau. Clic, derbyn, yn ôl at dy goffi.","dl.windows":"Ap Windows","dl.browser":"Ei redeg yn dy borwr","dl.soon":"Yn dod yn fuan","dl.notify":"🔔 Dwed wrtha i pan fydd yn agor","dl.notifySmall":"Alffa neu beta","hero.secondary":"Ystwyth, ond does byth angen coffi stand-yp ar y tîm. (Maen nhw'n cynnal stand-yps beth bynnag.)","pitch.h2":"AI-gile mewn cymaint o eiriau ag y mynni","pitch.lede":"Dewis hyd, o un gair i 144. Mae pob hyd yn ddisgrifiad ar wahân, wedi'i ysgrifennu ar gyfer y maint hwnnw. Llusga'r llithrydd neu defnyddia'r bysellau saeth.","pitch.rangeLabel":"Hyd mewn geiriau","pitch.dice":"🎲 fersiwn arall","pitch.words.one":"{n} gair","pitch.words.other":"{n} gair","pitch.letters.one":"{n} llythyren","pitch.letters.other":"{n} llythyren","pitch.chars.one":"{n} nod","pitch.chars.other":"{n} nod","count.line.html.one":"{n} cerdyn ar y bwrdd ar hyn o bryd","count.line.html.other":"{n} cerdyn ar y bwrdd ar hyn o bryd","features.aria":"Beth mae'n ei wneud","f.pile.h":"Un pentwr i ti","f.pile.html":"Mae <b>I ti</b> yn dal popeth sy'n aros amdanat ti, ar draws pob prosiect: cwestiynau, pethau i'w profi, tasgau na all neb ond person eu gwneud. Mae dy giw yn dweud beth sy'n dod nesaf a faint o amser mae'n ei gymryd.","f.sleep.h":"Timau sy'n gweithio tra byddi di'n cysgu","f.sleep.p":"Mae gan bob prosiect arweinydd a thîm o asiantau AI. Gwna sylw ar gerdyn ac mae'r tîm yn deffro, yn gwneud y gwaith ac yn ei roi'n ôl i ti gyda chamau y gall person blinedig eu dilyn.","f.tester.h":"Mae profwr AI yn gwirio gyntaf","f.tester.p":"Cyn i unrhyw beth gyrraedd atat ti, mae profwr yn dilyn y camau mewn copi o'r ap ac yn dangos beth a welodd, gyda sgrinlun. Bwria olwg dros y rhai a lwyddodd a derbyn gydag un clic.","f.proof.h":"Prawf, nid addewidion","f.proof.p":"Mae pob trosglwyddiad yn dangos beth sydd wedi newid: y ffeiliau, y gwahaniaethau, y sgrinluniau. Dim angen agor pob ap i weld a yw wedi'i orffen.","f.chat.h":"Sgwrsio gyda dy arweinwyr","f.chat.p":"Bar tebyg i Discord: un eicon i bob prosiect, diemwntau porffor ar gyfer beth sydd â'th angen di. Anfona syniad at arweinydd; maen nhw'n ei droi'n gardiau ac yn gynllun, gyda botwm ✅ Go.","f.tidy.h":"Yn cadw trefn ei hun","f.tidy.p":"Mae cardiau perthnasol yn cael eu plygu'n un, teitlau dryslyd yn cael eu trwsio, ac mae gwiriad tocynnau yn cadw'r cod yn denau. Llai o bethau i newid rhyngddyn nhw, llai i feddwl amdano.","f.private.h":"Dy un di, ar dy gyfrifiadur","f.private.li1":"Mae'r bwrdd yn rhedeg ar dy beiriant dy hun ac yn ateb dim ond ti.","f.private.li2":"Mae negeseuon preifat rhwng pobl wedi'u hamgryptio o un pen i'r llall.","f.private.li3":"Dim cyfrifon, dim tracwyr, dim cwcis.","f.lang.h":"Yn dy iaith di","f.lang.p":"Dros 120 o ieithoedd, o Iseldireg, Cymraeg a Japaneg i fôr-leidr, Yoda a Klingon, gyda newid cyflym yn ôl i'r Saesneg ar gyfer geiriau'r datblygwyr.","tl.aria":"Llinell amser o'r sgwrs gyntaf i'r map ffordd","tl.h2":"O'r sgwrs gyntaf i'r hyn sy'n dod nesaf","tl.lede":"Dyddiadau ac amserau go iawn, yn dy gylchfa amser dy hun. Ar ôl heddiw, y cynllun yw hwn, heb addo dyddiadau.","tl.today":"Heddiw","tl.planned":"wedi'i gynllunio","tl.cards.one":"{n} cerdyn","tl.cards.other":"{n} cerdyn","join.h2":"Ymuna","join.lede":"Mae AI-gile yn cael ei adeiladu gan un person bach a nifer fawr o asiantau amyneddgar. Mae'n breifat am y tro, mewn alffa caeedig gyda ffrindiau. Hoffet ti gael cynnig arni pan fydd yn agor?","join.btn":"Cofrestru diddordeb","join.small":"Anfonwn e-bost atat, dim byd arall","footer.tag":"AI-gile. Dim tracwyr, dim cwcis, dim coffi stand-yp.","footer.licence":"Trwydded busnes","footer.status":"Statws","form.sending":"Yn anfon…","form.failed":"Wnaeth hynny ddim gweithio: rho gynnig arni eto yn nes ymlaen.","form.offline":"Methu cyrraedd AI-gile: rho gynnig arni eto yn nes ymlaen.","interest.title":"AI-gile: dwed wrtha i pan fydd yr alffa'n agor","interest.description":"Gad dy e-bost i glywed pan fydd alffa caeedig neu beta AI-gile yn agor.","interest.h1":"🔔 Dwed wrtha i pan fydd yn agor","interest.lede":"Mae AI-gile mewn cyn-alffa caeedig. Gad dy e-bost ac fe ysgrifennwn unwaith, pan fydd lle i ti.","interest.email":"Dy e-bost","interest.which":"Pa brawf?","interest.alpha":"Alffa caeedig: cynnar, garw, llawer o newidiadau","interest.beta":"Beta: mwy sefydlog, yn hwyrach","interest.both":"Y naill neu'r llall, pa un bynnag ddaw gyntaf","interest.submit":"Rho fi ar y rhestr","interest.thanks":"Diolch! Rwyt ti ar y rhestr.","interest.kept":"Dim ond dy e-bost a'r prawf a ddewisaist sy'n cael eu cadw, ar gyfer y rhestr hon yn unig. Dim cylchlythyr, dim tracwyr.","licence.title":"AI-gile: trwydded busnes","licence.description":"Yn defnyddio AI-gile yn dy fusnes? Gwna gais am drwydded busnes am ddim.","licence.h1":"📜 Trwydded busnes","licence.lede":"Yn defnyddio AI-gile yn y gwaith? Dwed wrthon ni pwy wyt ti a beth rwyt ti'n ei wneud. Os yw'n gwneud rhywfaint o les, mae'r drwydded am ddim.","licence.company":"Cwmni","licence.website":"Gwefan","licence.what":"Beth rwyt ti'n ei wneud","licence.how":"Sut mae'n helpu'r byd","licence.email":"E-bost","licence.submit":"Gwneud cais","licence.thanks":"Diolch! Fe atebwn ni drwy e-bost.","status.title":"Statws AI-gile","status.h1":"Statws AI-gile","status.quiet":"Pob dim yn dawel","status.checking":"Yn gwirio…","status.offline":"Methu cyrraedd y gwasanaeth statws ar hyn o bryd (yn ceisio eto)","status.updated":"wedi'i ddiweddaru {ago}","status.justNow":"eiliad yn ôl","status.min":"{n} mun yn ôl","status.hours":"{n} awr yn ôl","status.days":"{n} diwrnod yn ôl","live.h2":"Gwyliwch ef yn cael ei adeiladu, yn fyw","live.caption":"Mae pob cerdyn wedi'i guddio: rydych chi'n gweld siâp y gwaith, nid y geiriau.","live.watching.one":"yn fyw: {n} yn gwylio","live.watching.other":"yn fyw: {n} yn gwylio","live.offline":"Mae'r bwrdd byw yn cael hoe fach. Dewch yn ôl yn fuan.","live.cols":"Backlog|I'w wneud|Ar y gweill|Y tîm yn gwirio|I ti i'w test|I'r tîm|Wedi'i wneud"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robotiaid.","Dirprwywyd."]},{"n":2,"texts":["Kanban robotiaid.","Asiantau, trefnus.","Syniadau'n realiti."]},{"n":3,"texts":["Kanban i robotiaid.","Syniadau'n troi'n nodweddion.","Kanban asiantau, am ddim."]},{"n":5,"texts":["Bwrdd kanban dan law asiantau.","Ti'n ysgrifennu cardiau. Asiantau'n adeiladu.","Am ddim, lleol, profedig, hwyliog."]},{"n":8,"texts":["Bwrdd kanban am ddim lle mae asiantau AI yn gweithio.","Ysgrifenna syniad. Mae asiantau'n ei adeiladu. Ti sy'n derbyn.","Ystwyth i un person a llawer o robotiaid amyneddgar."]},{"n":13,"texts":["Bwrdd kanban ar dy gyfrifiadur lle mae asiantau AI yn codi'r cardiau.","Ysgrifenna syniad. Tîm o asiantau'n ei adeiladu. Profwr yn ei wirio. Ti sy'n dweud ie.","Am ddim, dim cyfrifon, dim tracwyr: bwrdd, ychydig o robotiaid, a ti wrth y llyw."]},{"n":21,"texts":["Bwrdd kanban yw AI-gile ar gyfer gweithio gydag asiantau AI sy'n codio. Maen nhw'n codi'r cardiau; ti sy'n eu profi a'u derbyn.","Mae pob prosiect yn cael arweinydd a thîm o asiantau AI. Gwna sylw ar unrhyw gerdyn ac mae'r tîm yn mynd ati'n syth.","Bwrdd tasgau personol, am ddim, sy'n rhedeg ar dy gyfrifiadur dy hun. Robotiaid yw'r gweithwyr. Y sawl sy'n dweud ie yw ti."]},{"n":34,"texts":["Rwyt ti'n rhoi syniadau ar fwrdd. Mae tîm o asiantau AI yn eu troi'n nodweddion sy'n gweithio, yn eu profi ac yn eu dychwelyd gyda chamau i'w trio. Dim byd wedi'i wneud nes dy fod ti'n dweud.","Bwrdd kanban cartref yw AI-gile a adeiladodd Rich gyda llawer o help gan yr asiantau mae bellach yn eu rheoli. Mae am ddim, yn rhedeg ar dy gyfrifiadur, ac yn cael ei rannu gyda ffrindiau, nid ei werthu.","Dychmyga fwrdd kanban cyffredin, â cholofnau o'r Backlog hyd at Wedi'i wneud, ond bod asiantau AI yn codi'r cardiau. Maen nhw'n adrodd ar gynnydd, yn holi pan fyddan nhw'n sownd, ac yn aros bob amser am dy fawd i fyny."]},{"n":55,"texts":["Bwrdd kanban yw AI-gile lle mae'r tîm wedi'i wneud o asiantau AI. Mae gan bob prosiect arweinydd sy'n cynllunio'r gwaith a chynorthwywyr sy'n ei adeiladu. Pan fydd nodwedd yn barod, mae profwr AI yn ei thrio ac yn tynnu sgrinlun, ac yna mae'n glanio yn dy bentwr. Derbyn hi, neu wna sylw ac maen nhw'n ei hailwneud.","Dechreuodd fel ffordd un person o gadw trefn ar lawer o sesiynau codio AI ar unwaith, a thyfodd yn fwrdd go iawn. Mae'n rhedeg ar dy beiriant, heb angen cyfrif, a heb dracwyr. Mae am ddim i ffrindiau ac i'r chwilfrydig. Mae hefyd heb ei orffen, felly disgwyl ymylon garw a syndod bach o bryd i'w gilydd.","Dyma'r fersiwn onest. Rhaid i ti gael y syniadau o hyd, a rhaid i ti wirio'r canlyniadau o hyd. Mae AI-gile yn gwneud popeth rhyngddynt: mae'n cadw'r cardiau mewn trefn, yn deffro'r asiant iawn pan wnei di sylw, yn dangos yn union beth sydd wedi newid, ac yn cadw'r cyfan mewn un pentwr byr i ti."]},{"n":89,"texts":["Bwrdd kanban am ddim yw AI-gile y gelli di ei redeg ar dy gyfrifiadur dy hun. Yn lle pobl, mae gan bob prosiect dîm o asiantau AI: arweinydd sy'n troi dy syniadau'n gardiau ac yn gynllun, a chynorthwywyr sy'n codi'r cardiau yn nhrefn blaenoriaeth. Pan fydd rhywbeth wedi'i adeiladu, mae profwr AI yn dilyn y camau prawf ac yn dangos i ti beth a welodd. Yna mae'n aros mewn un pentwr o'r enw I ti. Rwyt ti'n ei dderbyn, neu'n gwneud sylw ac mae'r tîm yn cael cynnig arall. Does dim byd yn cyrraedd Wedi'i wneud hebddot ti.","Rhai pethau na fyddi di'n eu disgwyl efallai. Mae gwyliwr nos yn cadw'r golofn I'w wneud yn llawn tra byddi di'n cysgu, gan ddewis cardiau nad oes angen ateb gennyt ti arnyn nhw. Mae cownter tocynnau yn dangos faint mae'r asiantau wedi'i ddefnyddio heddiw a'r wythnos hon, ac mae Modd Dim Tocynnau yn dweud wrthyn nhw am roi'r gorau i wario. Mae'r bwrdd yn siarad tua 120 o ieithoedd, gan gynnwys Iseldireg, Fflemeg, môr-leidr a Klingon. Does dim un o hyn yn costio ceiniog, ac nid oes neb yn ceisio ei werthu i ti chwaith.","Prosiect bach, personol yw AI-gile, nid cwmni. Roedd Rich eisiau gofalu am sawl prosiect codio AI heb agor pob ap i'w gwirio, felly adeiladodd ef a'r asiantau fwrdd ar ei gyfer, ac yna defnyddio'r bwrdd i adeiladu gweddill eu hunain. Mae mewn cyn-alffa caeedig, sy'n golygu ei fod yn gweithio, gan amlaf, i lond llaw o ffrindiau. Does dim tudalen brisiau, dim cylchlythyr a dim cynllun twf. Os yw'n swnio'n ddefnyddiol, gelli di ofyn am gael ei drio pan fydd yn agor ychydig yn fwy."]},{"n":144,"texts":["Bwrdd kanban yw AI-gile ar gyfer un person a llawer o asiantau AI. Mae'n rhedeg ar dy gyfrifiadur dy hun ac mae'n hollol rad ac am ddim. Rwyt ti'n ychwanegu prosiectau, ac mae pob prosiect yn cael arweinydd a thîm bach. Rwyt ti'n sgwrsio gyda'r arweinydd, ychydig fel ar Discord, ac yn disgrifio syniad; mae'r arweinydd yn ei droi'n gardiau ac yn gynllun, yna'n aros i ti wasgu Go. Mae'r tîm yn gweithio drwy'r cardiau yn nhrefn blaenoriaeth, gan ddefnyddio llinell orchymyn syml a wnaed ar gyfer modelau iaith. Cyn i unrhyw beth ddod yn ôl atat ti, mae profwr AI yn dilyn y camau mewn copi o'r ap ac yn atodi sgrinlun. Mae gwaith gorffenedig yn glanio yn dy bentwr gyda'r ffeiliau a newidiwyd a'r gwahaniaethau. Rwyt ti'n ei dderbyn, neu'n gadael sylw ac mae'r tîm yn deffro ac yn rhoi cynnig arall arni. Dim ond ti all symud cerdyn i Wedi'i wneud. Does dim cyfrifon, dim tracwyr a dim cwcis, ac mae'r cyfan yn aros ar dy gyfrifiadur.","Diwrnod gydag AI-gile, fwy neu lai. Gyda'r nos, rwyt ti'n gadael ychydig o sylwadau: mae'r botwm hwn yn y lle anghywir, dylai'r rhestr honno gael ei threfnu, allen ni gael modd tywyll. Rwyt ti'n mynd i'r gwely. Mae'r asiantau'n darllen y sylwadau, yn gwneud y newidiadau, yn eu profi ac yn eu rhoi'n ôl i ti. Os bydd I'w wneud yn mynd yn wag, mae'r gwyliwr nos yn ei lenwi o'r backlog gyda chardiau nad oes angen ateb gennyt ti arnyn nhw. Yn y bore, mae un pentwr byr: cwpl o gwestiynau ac ychydig o bethau i'w trio, pob un â chamau y gall person cysglyd eu dilyn a sgrinlun ohono'n gweithio. Rwyt ti'n clicio drwyddyn nhw, yn derbyn y rhai da ac yn anfon y gweddill yn ôl. Mae cownter tocynnau yn dangos beth ddefnyddiodd y cyfan, ac mae Modd Dim Tocynnau yno ar gyfer wythnosau main. Yna rwyt ti'n cael brecwast, a all yr asiantau ddim helpu gyda hynny eto.","Yn gyntaf, beth nad yw AI-gile. Nid cwmni newydd mohono, nid yw ar werth, ac nid oes neb yn casglu dy ddata. Bwrdd rhad ac am ddim ydyw sy'n rhedeg ar dy gyfrifiadur, heb gyfrifon, heb dracwyr a heb gwcis. Beth ydyw: un lle taclus i weld pob prosiect codio AI ar unwaith, gyda thîm o asiantau'n gwneud y cardiau a ti'n gwneud y penderfyniadau. Mae'n plygu cardiau perthnasol at ei gilydd, yn trwsio teitlau dryslyd, ac yn cadw llygad ar ba mor denau mae'r cod yn aros. Mae'n siarad tua 120 o ieithoedd, o Iseldireg a Fflemeg i fôr-leidr a Klingon. Gall ffrindiau anfon neges at ei gilydd, yn breifat ac wedi'i hamgryptio. Fe'i hadeiladwyd gan Rich a nifer fawr o asiantau amyneddgar, gan ddefnyddio ei hun gan amlaf. Mae mewn cyn-alffa caeedig, felly mae'n arw mewn mannau. Os yw'n swnio'n hwyl, gofyn yn gwrtais ac efallai y cei di fynd i mewn yn gynnar."]}],"quips":{"1":"Un gair. Eofn. Efallai'n rhy eofn.","3":"Tri gair. Eisoes yn fwy gonest na'r rhan fwyaf o dudalennau cynnyrch.","8":"Wyth gair. Yn dal yn fyrrach na stand-yp.","21":"Pwyntiau stori yw'r hydoedd, gyda llaw. Wrth gwrs eu bod nhw.","55":"Pum deg pump gair. Gorffennwyd dau gerdyn tra oeddet ti'n darllen hwnna.","144":"Honna yw'r un hir. Does dim 233. Mae'r asiantau wedi mynd i'r gwely."}},"timeline":{"first-idea.name":"Y syniad cyntaf","first-idea.line":"Y sgwrs gyntaf un, cyn bod unrhyw god yn bodoli.","first-board.name":"Y bwrdd cyntaf","first-board.line":"Bwrdd sy'n olrhain ei adeiladu ei hun: cardiau, colofnau, llusgo a gollwng, prosiectau.","team-roles.name":"Tîm a rolau","team-roles.line":"Proffiliau asiantau, templedi tîm, mannau a phwy sy'n gwneud beth.","install.name":"Gosod a fersiynau","install.line":"Zip y gall ffrind ei osod, hunan-ddiweddaru, sianeli a dychwelyd yn ôl.","usage-saver.name":"Arbed defnydd","usage-saver.line":"Mesur beth mae rhediadau'n ei gostio, cadw'r cod yn denau, arbed dy derfyn.","friends.name":"Ffrindiau a rhannu","friends.line":"Negeseuon preifat, cyfnewidfa ddryslyd, gwahoddiadau, rolau a phrosiectau a rennir.","languages.name":"Ieithoedd","languages.line":"Pob testun sgrin mewn ffeil iaith, gydag Iseldireg a Fflemeg yn gyntaf.","ai-tester.name":"Profwr AI","ai-tester.line":"Mae profwr yn gwirio pob trosglwyddiad yn gyntaf ac yn dangos beth a welodd.","website.name":"Y wefan","website.line":"aigile.lol, y rhagflas a'r llinell amser hon.","streaming.name":"Sgwrsio a ffrydio","streaming.line":"Discord, Twitch, OBS, modd ffrydiwr, GIFs ac emojis.","no-ai.name":"Rhifyn Dim AI","no-ai.line":"Bwrdd i bobl sy'n codio heb AI, a byrddau cyhoeddus.","night-watch.name":"Gwylio'r nos","night-watch.line":"Gwyliwr a Scrum Master yn cadw'r timau ar dasg tra byddi di'n cysgu.","p-more.name":"Popeth arall","p-more.line":"Syniadau llai sy'n dal i aros eu tro.","p-android.name":"Ffôn ac Android","p-android.line":"Cyrraedd dy fwrdd o ffôn, yna ap Android brodorol.","p-release.name":"Alffa a thu hwnt","p-release.line":"Alffa caeedig, y wefan fyw, yna beta.","p-languages.name":"Mwy o ieithoedd","p-languages.line":"Mwy na chant o ieithoedd, a modd trochi i ddysgwyr.","p-engines.name":"Mwy o beiriannau AI","p-engines.line":"Dewis Claude, Codex neu Gemini i bob asiant.","p-pro.name":"Arfer proffesiynol","p-pro.line":"Labeli risg, pyrth cyfuno, cardiau digwyddiad a rheiliau diogelu.","p-self.name":"Gofalu amdanat ti","p-self.line":"Modd blinedig, nodiadau atgoffa hunanofal a 4:20.","p-servers.name":"Gweinyddion a graddfa","p-servers.line":"Gosodiadau gweinydd byd-eang, rolau a chynllunio ar gyfer twf.","p-livestream.name":"Ychwanegion ffrydio","p-livestream.line":"Sgwrs Twitch, emojis personol a golwg fyw gyhoeddus."}};
